// 1990s Meta: decks people registered or commonly played between 1994 and 1998, under the names players used then.
// Hand-written (not generated by test/build_decks.mjs). decks.js merges these into DECK_LISTS / DECK_META.
// Card pool is Alpha to Legends, so later cards are left out and each blurb says what changed.
// rating follows the other decks: the win rate with the AI at the wheel (270-game soak), not the deck's historical standing.
// `source: 'list'` = a registered tournament list. `source: 'archetype'` = a representative build of a named archetype.
const M = (name, colors, archetype, year, pilot, source, rating, keyCards, blurb) =>
  ({ name, colors, archetype, blurb, aiLevelHint: 'normal', rating, pool: '90s', meta: '90s', year, pilot, source, keyCards });

